functions.mk865SellItem:
function mk865SellItem(type,id,rate){
 const key=mk865ItemKey(type,id);if(MK865_SALE_LOCKS.has(key))return;normalizeShop();const e=mk865SellEligibility(type,id);if(!e.ok){mk865OpenSellDialog(type,id);return}
 const r=Number(rate)===MK865_REFUND_TRAINING?MK865_REFUND_TRAINING:MK865_REFUND_NOW,m=mk865MissionForItem(type,id);if(r===MK865_REFUND_TRAINING&&(!m||m.status!=="completed")){mk865OpenSellDialog(type,id);return}
 MK865_SALE_LOCKS.add(key);try{
  const refund=Math.floor(e.paidPrice*r);state.inventory[type]=(state.inventory[type]||[]).filter(x=>x!==id);mk865FallbackAfterSale(type,id,state);state.coins=Math.max(0,Number(state.coins||0)+refund);state.shopStats.sales=Math.max(0,Number(state.shopStats.sales||0)+1);state.shopStats.refundedCoins=Math.max(0,Number(state.shopStats.refundedCoins||0)+refund);
  const soldAt=Date.now(),transactionId=`sale_${soldAt.toString(36)}_${Math.random().toString(36).slice(2,8)}`;state.saleHistory=[...(state.saleHistory||[]),{transactionId,type,id,itemName:e.item.name,source:"store",paidPrice:e.paidPrice,purchaseTimestamp:e.acq.purchaseTimestamp,soldAt,refundRate:r,refundCoins:refund}].slice(-MK865_SALE_HISTORY_LIMIT);e.acq.soldTimestamp=soldAt;e.acq.lastRefundRate=r;e.acq.lastRefundCoins=refund;mk865RememberEverOwned(state,type,id);if(m)state.saleMission=null;save();mk865CloseSaleOverlay();rewardPop(`Продано: +${refund} 🪙`);openShop(type)
 }finally{setTimeout(()=>MK865_SALE_LOCKS.delete(key),450)}
}

