 if(type==='achievements'){
  return mk872ActiveCollectionItems(type).filter(item=>isAchievementUnlocked(state,item.id));
 }
 const owned=new Set(Array.isArray(state.inventory?.[type])?state.inventory[type]:[]);
 return mk872ActiveCollectionItems(type).filter(item=>owned.has(item.id));
