functions.mk873ArchiveRows:
function mk873ArchiveRows(profile=state){
 const ids=new Set();
 for(const id of profile?.inventory?.avatars||[])ids.add(id);
 for(const key of Object.keys(profile?.acquisitionMetadata||{}))if(key.startsWith('avatars:'))ids.add(key.slice(8));
 for(const key of profile?.everOwned||[])if(String(key).startsWith('avatars:'))ids.add(String(key).slice(8));
 for(const id of Object.keys(mk873Ledger(profile)))ids.add(id);
 for(const entry of profile?.saleHistory||[])if(entry?.type==='avatars')ids.add(entry.id);
 if(profile?.profileId)for(const key of Object.keys(mk873Registry()))if(key.startsWith(`${profile.profileId}:avatars:`))ids.add(key.slice(`${profile.profileId}:avatars:`.length));
 return [...ids].filter(mk873IsArchivedAvatar).map(id=>({id,item:catalogItem('avatars',id),eligibility:mk873Eligibility(profile,id)})).sort((a,b)=>a.item.name.localeCompare(b.item.name,'ru'));
}
